if isinstance(result, float) and result.is_integer():
    result = int(result)  # 6 / 2 gives 6.0; the answer 6 is still right
print(repr(result))
', '[{"input": "color_code(''black'')", "output": "0"}, {"input": "color_code(''white'')", "output": "9"}]'::jsonb, '[]'::jsonb, '[{"stdin": "color_code(''black'')", "expected_output": "0"}, {"stdin": "color_code(''white'')", "expected_output": "9"}, {"stdin": "color_code(''orange'')", "expected_output": "3"}, {"stdin": "colors()", "expected_output": "[''black'', ''brown'', ''red'', ''orange'', ''yellow'', ''green'', ''blue'', ''violet'', ''grey'', ''white'']"}]'::jsonb, '{"source": "exercism/python@6105f6d9d3ef66ce3d5c8f529d2882af3d76b706", "slug": "resistor-color", "license": "MIT"}'::jsonb);
