call = ast.parse(input(), mode="eval").body
args = [ast.literal_eval(arg) for arg in call.args]
result = globals()[call.func.id](*args)
if isinstance(result, float) and result.is_integer():
    result = int(result)  # 6 / 2 gives 6.0; the answer 6 is still right
print(repr(result))
', '[{"input": "proteins(''AUG'')", "output": "[''Methionine'']"}, {"input": "proteins(''UUU'')", "output": "[''Phenylalanine'']"}]'::jsonb, '[]'::jsonb, '[{"stdin": "proteins(''AUG'')", "expected_output": "[''Methionine'']"}, {"stdin": "proteins(''UUU'')", "expected_output": "[''Phenylalanine'']"}, {"stdin": "proteins(''UUC'')", "expected_output": "[''Phenylalanine'']"}, {"stdin": "proteins(''UUA'')", "expected_output": "[''Leucine'']"}, {"stdin": "proteins(''UUG'')", "expected_output": "[''Leucine'']"}, {"stdin": "proteins(''UCU'')", "expected_output": "[''Serine'']"}, {"stdin": "proteins(''UCC'')", "expected_output": "[''Serine'']"}, {"stdin": "proteins(''UCA'')", "expected_output": "[''Serine'']"}, {"stdin": "proteins(''UCG'')", "expected_output": "[''Serine'']"}, {"stdin": "proteins(''UAU'')", "expected_output": "[''Tyrosine'']"}, {"stdin": "proteins(''UAC'')", "expected_output": "[''Tyrosine'']"}, {"stdin": "proteins(''UGU'')", "expected_output": "[''Cysteine'']"}, {"stdin": "proteins(''UGC'')", "expected_output": "[''Cysteine'']"}, {"stdin": "proteins(''UGG'')", "expected_output": "[''Tryptophan'']"}, {"stdin": "proteins(''UAA'')", "expected_output": "[]"}, {"stdin": "proteins(''UAG'')", "expected_output": "[]"}, {"stdin": "proteins(''UGA'')", "expected_output": "[]"}, {"stdin": "proteins(''UUUUUU'')", "expected_output": "[''Phenylalanine'', ''Phenylalanine'']"}, {"stdin": "proteins(''UUAUUG'')", "expected_output": "[''Leucine'', ''Leucine'']"}, {"stdin": "proteins(''AUGUUUUGG'')", "expected_output": "[''Methionine'', ''Phenylalanine'', ''Tryptophan'']"}, {"stdin": "proteins(''UAGUGG'')", "expected_output": "[]"}, {"stdin": "proteins(''UGGUAG'')", "expected_output": "[''Tryptophan'']"}, {"stdin": "proteins(''AUGUUUUAA'')", "expected_output": "[''Methionine'', ''Phenylalanine'']"}, {"stdin": "proteins(''UGGUAGUGG'')", "expected_output": "[''Tryptophan'']"}, {"stdin": "proteins(''UGGUGUUAUUAAUGGUUU'')", "expected_output": "[''Tryptophan'', ''Cysteine'', ''Tyrosine'']"}, {"stdin": "proteins(''AUGAUG'')", "expected_output": "[''Methionine'', ''Methionine'']"}]'::jsonb, '{"source": "exercism/python@6105f6d9d3ef66ce3d5c8f529d2882af3d76b706", "slug": "protein-translation", "license": "MIT"}'::jsonb);
